21	/* ---- newlib stubs ------------------------------------------------------
22	 *
23	 * stat family note: the guest's struct bounces through the window BOTH
24	 * ways, so fields the host does not fill keep the caller's values (the
25	 * hosts write pico_stat's st_mode/st_size at their newlib offsets). */
26	
27	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
28	{
29	  if (fd > 2)
30	    return htif_write(fd, ptr, len);
31	  for (size_t i = 0; i < len; ++i)
32	    htif_uart_putc(((const char*) ptr)[i]);
33	  return (ssize_t) len;
34	}
35	
36	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
37	{
38	  if (fd > 2)
39	    return htif_read(fd, buf, len);
40	  return 0; /* no console input on either engine: EOF */
41	}
42	
43	__attribute__((used)) int _fstat(int fd, struct stat* st)
44	{
45	  if (fd > 2) {
46	    htif_win_store(0, st, sizeof(*st));
47	    intptr_t ret = htif_syscall(VH_SYS_FSTAT, fd, WIN_DATA_VA, 0, 0);
48	    if (ret == 0)
49	      htif_win_load(st, 0, sizeof(*st));
50	    return (int) ret;
51	  }
52	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
53	  return 0;
54	}
