77	__attribute__((used)) int _openat(int dirfd, const char* name, int flags, ...)
78	{
79	  if (htif_win_store_str(0, name) == (size_t) -1)
80	    return -1;
81	  return (int) htif_syscall(VH_SYS_OPENAT, dirfd, WIN_DATA_VA, flags, 0);
