84	__attribute__((used)) int _stat(const char* file, struct stat* st)
85	{
86	  size_t stoff = htif_win_store_str(0, file);
87	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
88	    return -1;
89	  htif_win_store(stoff, st, sizeof(*st));
90	  intptr_t ret =
91	    htif_syscall(VH_SYS_STAT, WIN_DATA_VA, WIN_DATA_VA + stoff, 0, 0);
92	  if (ret == 0)
93	    htif_win_load(st, stoff, sizeof(*st));
94	  return (int) ret;
95	}
