111	                                   struct stat* st, int flags)
112	{
113	  size_t stoff = htif_win_store_str(0, file);
114	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
115	    return -1;
116	  htif_win_store(stoff, st, sizeof(*st));
117	  intptr_t ret = htif_syscall(VH_SYS_FSTATAT, dirfd, WIN_DATA_VA,
118	                              WIN_DATA_VA + stoff, flags);
119	  if (ret == 0)
120	    htif_win_load(st, stoff, sizeof(*st));
121	  return (int) ret;
122	}
