130	                                     int flags)
131	{
132	  if (htif_win_store_str(0, file) == (size_t) -1)
133	    return -1;
134	  return (int) htif_syscall(VH_SYS_FACCESSAT, dirfd, WIN_DATA_VA, mode, flags);
